import {platformIcon} from './platform-icons.mjs?v=20261026';
import {setVrsText} from './branding.mjs';
const social=!!document.querySelector('[data-social-directory]');
const $=selector=>document.querySelector(selector),status=$('[data-directory-status]'),listForm=$('[data-directory-list-form]'),linkForm=$('[data-directory-link-form]');
let admin=false,lists=[];
const node=(tag,text='',className='')=>{const element=document.createElement(tag);if(text)setVrsText(element,text);if(className)element.className=className;return element;};
async function api(path,method='GET',data){const response=await fetch('/api/club/'+(social?'social/':'directory/')+path,{method,cache:'no-store',...(data?{headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const body=await response.json();if(!response.ok)throw Error(body.error||'No se pudo completar la operación.');return body;}
function resetList(){listForm.reset();listForm.elements.id.value='';$('[data-list-form-title]').textContent='Crear lista';$('[data-list-cancel]').hidden=true;}
function resetLink(){linkForm.reset();linkForm.elements.id.value='';$('[data-link-form-title]').textContent='Añadir página o red social';$('[data-link-cancel]').hidden=true;}
function brandWatermark(url,platform,name='',custom=''){let source='';if(typeof custom==='string'&&/^https?:\/\//i.test(custom))source=custom;else{const icon=platformIcon(url,platform);if(icon)source=icon.src;else{try{const host=new URL(url).hostname;source='https://www.google.com/s2/favicons?domain='+encodeURIComponent(host)+'&sz=256';}catch{}}}if(!source)return null;const img=node('img','','directory-brand-watermark');img.src=source;img.alt='';img.loading='lazy';img.decoding='async';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();return img;}
function instagramAvatar(value){try{const raw=String(value||'').trim();const url=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw);if(!/(^|\.)instagram\.com$/i.test(url.hostname))return '';const parts=url.pathname.split('/').filter(Boolean);if(parts.length!==1)return '';const username=parts[0].replace(/^@/,'');if(!/^[a-z0-9._]{1,30}$/i.test(username)||['p','reel','reels','stories','tv','accounts','direct','explore','about','developer','legal'].includes(username.toLowerCase()))return '';return 'https://unavatar.io/instagram/'+encodeURIComponent(username);}catch{return '';}}function tools(edit,remove,label){const bar=node('div','','directory-tools');for(const [title,action]of [['Editar',edit],['Eliminar',remove]]){const button=node('button',title+' '+label);button.type='button';button.addEventListener('click',action);bar.append(button);}return bar;}
function renderEntry(entry,list,target){const card=node('article','','directory-link');const watermark=brandWatermark(entry.url,entry.platform,entry.name,entry.icon_url||entry.logo_url||entry.image_url);if(watermark)card.append(watermark);const avatarUrl=list.kind==='collaborators'?instagramAvatar(entry.url):'';if(avatarUrl){const avatar=node('img','','directory-instagram-avatar');avatar.src=avatarUrl;avatar.alt='Foto de perfil de Instagram de '+entry.name;avatar.loading='lazy';avatar.decoding='async';avatar.referrerPolicy='no-referrer';avatar.onerror=()=>{if(avatar.dataset.fallbackTried!=='1'){avatar.dataset.fallbackTried='1';avatar.src='https://unavatar.io/instagram/'+encodeURIComponent((instagramAvatar(entry.url).split('/').pop()||'').split('?')[0]);}else avatar.remove();};card.append(avatar);}const icon=platformIcon(entry.url,entry.platform);if(icon)card.append(icon);card.append(node('small',(list.kind==='collaborators'?'COLABORADOR':'SITIO DE INTERÉS')+' · '+list.name),node('h3',entry.name));if(entry.description)card.append(node('p',entry.description));const link=node('a','Abrir '+entry.platform+' ↗');link.href=entry.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);if(admin)card.append(tools(()=>{for(const key of ['id','name','url','description','platform'])linkForm.elements[key].value=entry[key]||'';linkForm.elements.listId.value=entry.list_id;$('[data-link-form-title]').textContent='Editar enlace';$('[data-link-cancel]').hidden=false;linkForm.scrollIntoView({block:'start',behavior:'instant'});linkForm.elements.name.focus({preventScroll:true});},async()=>{if(!confirm('¿Eliminar el enlace «'+entry.name+'»?'))return;try{await api('links/'+entry.id,'DELETE');if(linkForm.elements.id.value===entry.id)resetLink();await load();status.textContent='Enlace eliminado.';}catch(error){status.textContent=error.message;}},'enlace'));
 target.append(card);}
async function load(){lists=await api('lists');const collections=await Promise.all(lists.map(async list=>{try{return [list,(await api('links?list='+encodeURIComponent(list.id)))];}catch{return [list,[]];}}));const grid=$('[data-directory-lists]'),selectedFolder=linkForm.elements.listId.value;grid.replaceChildren();linkForm.elements.listId.replaceChildren();for(const [list,entries]of collections){const option=node('option',list.name);option.value=list.id;linkForm.elements.listId.append(option);if(admin){const group=node('section','','directory-list-group'),header=node('div','','directory-list-heading');header.append(node('small',list.kind==='collaborators'?'COLABORADORES':'SITIOS DE INTERÉS'),node('h2',list.name));header.append(tools(()=>{listForm.elements.id.value=list.id;listForm.elements.name.value=list.name;listForm.elements.kind.value=list.kind;$('[data-list-form-title]').textContent='Editar lista';$('[data-list-cancel]').hidden=false;listForm.scrollIntoView({block:'start',behavior:'instant'});listForm.elements.name.focus({preventScroll:true});},async()=>{if(!confirm('¿Eliminar la lista «'+list.name+'»? Debe estar vacía.'))return;try{await api('lists/'+list.id,'DELETE');if(listForm.elements.id.value===list.id)resetList();await load();status.textContent='Lista eliminada.';}catch(error){status.textContent=error.message;}},'lista'));group.append(header);const cards=node('div','','directory-links');for(const entry of entries)renderEntry(entry,list,cards);if(!entries.length)cards.append(node('p','Esta lista todavía no tiene páginas o redes sociales.','directory-empty'));group.append(cards);grid.append(group);}else{for(const entry of entries)renderEntry(entry,list,grid);}}
if(selectedFolder&&lists.some(list=>list.id===selectedFolder))linkForm.elements.listId.value=selectedFolder;if(!grid.children.length)grid.append(node('p',admin?(social?'Crea tu primera lista de redes o sitios de interés.':'Crea tu primera lista para añadir colaboradores y sitios de interés.'):(social?'El club está preparando sus redes y sitios de interés.':'El club está preparando sus listas de colaboradores y sitios de interés.'),'directory-empty'));status.textContent=grid.querySelector('.directory-link')?(social?'Todas las redes y sitios publicados.':'Todos los colaboradores y sitios publicados.'):(social?'Todavía no hay redes o sitios publicados.':'Todavía no hay colaboradores publicados.');linkForm.querySelector('[type=submit]').disabled=!lists.length;}
listForm.addEventListener('submit',async event=>{event.preventDefault();const button=listForm.querySelector('[type=submit]');button.disabled=true;const note=$('[data-list-save-status]');try{const data=Object.fromEntries(new FormData(listForm));await api('lists'+(data.id?'/'+data.id:''),'POST',data);resetList();await load();note.textContent='Lista guardada.';}catch(error){note.textContent=error.message;}finally{button.disabled=false;}});
linkForm.addEventListener('submit',async event=>{event.preventDefault();const button=linkForm.querySelector('[type=submit]');button.disabled=true;const note=$('[data-link-save-status]');try{const data=Object.fromEntries(new FormData(linkForm));await api('links'+(data.id?'/'+data.id:''),'POST',data);resetLink();await load();note.textContent='Enlace guardado y publicado.';window.dispatchEvent(new Event('club-session-change'));}catch(error){note.textContent=error.message;}finally{button.disabled=false;}});
$('[data-list-cancel]').addEventListener('click',resetList);$('[data-link-cancel]').addEventListener('click',resetLink);
try{const response=await fetch('/api/admin/session',{cache:'no-store'});admin=response.ok&&!!(await response.json()).id;}catch{}
$('[data-directory-management]').hidden=!admin;$('[data-directory-login]').href=admin?'#gestion':'admin.html';$('[data-directory-login]').textContent=admin?'Gestionar listas y enlaces ↓':'Entrar para gestionar las listas';
try{await load();}catch(error){status.textContent=error.message;}
